// "We need a tiny scripting language for user macros. Easy: split on
// semicolons and handle each statement with regex + eval."
// Run it: node 71-tiny-lang/original.js

var variables = {}; // Problem 1: ONE flat global scope, forever.

function run(source) {
  // Problem 2: "parsing" = split(';'). A semicolon inside a string?
  // A block spanning statements? An if with an else? The format
  // can't even REPRESENT nesting — if/while below only accept ONE
  // statement, no blocks, no else.
  var statements = source.split(";");

  for (var i = 0; i < statements.length; i++) {
    var stmt = statements[i].trim();
    if (!stmt) continue;

    var m;
    if ((m = stmt.match(/^let (\w+) = (.+)$/))) {
      variables[m[1]] = evalExpr(m[2]);
    } else if ((m = stmt.match(/^print (.+)$/))) {
      console.log(evalExpr(m[1]));
    } else if ((m = stmt.match(/^if \((.+)\) (.+)$/))) {
      // one statement only. else? nested if? Impossible shapes.
      if (evalExpr(m[1])) run(m[2]);
    } else if ((m = stmt.match(/^while \((.+)\) (.+)$/))) {
      // ...and the while's body can't contain a ';' — split() above
      // already cut it off. Loops with more than one statement are
      // simply not writable.
      while (evalExpr(m[1])) run(m[2]);
    } else if ((m = stmt.match(/^(\w+) = (.+)$/))) {
      variables[m[1]] = evalExpr(m[2]);
    } else {
      // Problem 3: errors have no line numbers, no positions —
      // just the raw statement thrown back at you.
      throw new Error("what is this: " + stmt);
    }
  }
}

function evalExpr(expr) {
  // Problem 4: expressions are EVAL'D, with variables spliced in by
  // regex. All of project 69's security lesson, un-learned:
  // let x = process.exit(1) "works". And precedence, associativity,
  // error positions — all delegated to a JS engine evaluating code
  // we GENERATED.
  var substituted = expr.replace(/[a-zA-Z_]\w*/g, function (name) {
    return name in variables ? JSON.stringify(variables[name]) : name;
  });
  return eval(substituted);
}

// works — impressive for 40 lines, which is why this design survives
// code review:
run("let x = 3; let y = 4; print x * x + y * y");

// no scoping: the while's "body" variable is global, and leaks:
run("let i = 0; while (i < 3) i = i + 1; print i");
console.log("i leaked into globals:", variables.i);

// and the ceiling, immediately:
try {
  run("if (x > 2) { print 1; print 2; }"); // blocks: unrepresentable
} catch (e) {
  console.log("failed on a block:", e.message);
}

# 🏋️ Practice: A Tiny Interpreted Language

Do these after reading LEARN.md and the README. Solutions are at the bottom — try each exercise before peeking.

Exercises 2, 3, and 5 change the language — work on **copies** of the three `refactored/` files so the original tests keep passing.

## Exercises

### ⭐ 1. Write Tiny, not JavaScript: factorial (warm-up)

No interpreter changes. Write a Tiny program (as a string passed to `run`) that computes 10! with a `while` loop and prints the result. Check the returned array in node. The discipline: you may only use what Tiny has — `let`, `while`, `print`, arithmetic — there is no function call, no `for`, no `*=`.

What it practices: `run(source)` returns output as data, so a whole program is one assert.
Hint: two variables — the counter and the running product — and the loop multiplies then decrements.

Expected: `run(yourProgram)` → `['3628800']`.

### ⭐⭐ 2. Multi-value `print` (core)

Upgrade `print` to accept a comma-separated list: `print "x =", x, x * x;` prints one line, values joined by single spaces. Single-value `print` must keep working unchanged. This touches all three stages: the lexer doesn't even know `,` exists yet, the parser must loop, and the interpreter must join.

What it practices: threading one feature through lexer → parser → interpreter, the full pipeline.
Hint: add `,` to `ONE_CHAR`; in the `print` branch collect expressions `while (at(','))`; make the node carry `values` (an array) instead of `value`.

Expected: `run('let x = 2; print "x =", x, x * x;')` → `['x = 2 4']`, and `run('print 1;')` → `['1']`.

### ⭐⭐ 3. Logical `&&` and `||` (core)

Add boolean operators: `&&` binds tighter than `||`, and both bind *looser* than `==`, so `1 == 1 && 2 == 2` means `(1==1) && (2==2)`. Stay true to Tiny's strictness: both operands must be booleans — `1 && true` is a positioned error, not JavaScript-style truthiness.

What it practices: choosing binding powers relative to an existing table, plus Tiny's "no coercion" philosophy.
Hint: `TWO_CHAR` in the lexer; `'||': [1, 2], '&&': [2, 3]` in the parser's `INFIX`; a new branch at the top of `applyOp` using `requireType(..., 'boolean', ...)`.

Expected: `run('print true && false; print 1 < 2 || false; print 1 == 1 && 2 == 2;')` → `['false', 'true', 'true']`, and `run('print 1 && true;')` throws `/"&&" needs a boolean/`.

### ⭐⭐ 4. Test the untested corners (core)

No language changes — write tests (a scratch file using `node:test`, like `tiny.test.js`) pinning three behaviors the suite never checks: (a) string equality: `print "a" == "a";` prints `true` and `print "1" == 1;` prints `false`; (b) ordering on strings is an error: `run('print "a" < "b";')` throws; (c) the subtle one — assignment updates the *nearest* declaration: with `x` declared at two depths, an assignment two blocks deep must change the inner `x`, leaving the outer one alone.

What it practices: reading `valueEquals`, `applyOp`, and `Environment.assign` closely enough to predict them — then locking the predictions in.
Hint: for (c), print the inner `x` before the block closes and the outer `x` after, and assert the pair.

Expected: (a) and (b) as stated; for (c) a program shaped like `let x = 1; if (true) { let x = 2; if (true) { x = 10; } print x; } print x;` outputs `['10', '1']`.

### ⭐⭐⭐ 5. Add `break` (challenge)

Give Tiny a `break;` statement that exits the *innermost* `while` immediately. The interpreter walks the tree with plain recursive calls, so `break` has to escape from deep inside a block back to the loop — the classic trick is throwing a private signal class that the `while` case catches. Also handle abuse: `break;` outside any loop must become a friendly `TinyError`, not a leaked internal object.

What it practices: exceptions as non-local control flow — how real interpreters implement `break`, `continue`, and `return`.
Hint: `class BreakSignal {}` (not an Error!); `throw` it in a new `case 'break'`; wrap the `exec(node.body, env)` inside the `while` case in try/catch — catch only `instanceof BreakSignal`, rethrow everything else; convert stragglers at the top level of `run`.

Expected: a count-up loop inside `while (true)` that breaks at 3 outputs `['0', '1', '2', 'done']`; `run('break;')` throws `/"break" outside a loop/`; a `break` in an inner loop leaves the outer loop running.

## Solutions

### 1. Factorial in Tiny

```js
import { run } from './refactored/interpreter.js';
import assert from 'node:assert/strict';

assert.deepEqual(run(`
  let n = 10;
  let result = 1;
  while (n > 1) {
    result = result * n;
    n = n - 1;
  }
  print result;
`), ['3628800']);
```

WHY: exercises the language end to end — declarations, a multi-statement loop body (the exact thing `split(";")` could never represent), assignment reaching out to the enclosing scope, and output-as-returned-data making the whole program checkable with one `deepEqual`.

### 2. Multi-value `print`

```js
// lexer.js — ',' becomes a token:
const ONE_CHAR = new Set(['+', '-', '*', '/', '(', ')', '{', '}', ';', '=', '<', '>', '!', ',']);

// parser.js — the print branch collects a list:
    if (at('print')) {
      next();
      const values = [parseExpression(0)];
      while (at(',')) { next(); values.push(parseExpression(0)); }
      expect(';');
      return { type: 'print', values };
    }

// interpreter.js — evaluate each, join with spaces:
      case 'print':
        return void output.push(node.values.map((v) => stringify(evaluate(v, env))).join(' '));
```

WHY: a complete tour of the three-stage pipeline — the lexer learns a character, the parser learns a shape (note it's the same comma-separated-list loop the JSON parser used for arrays), and the interpreter learns what the shape *means*. Storing `values` as an array even for one value keeps the node uniform, so the single-value case needs no special code.

### 3. `&&` and `||`

```js
// lexer.js:
const TWO_CHAR = new Set(['==', '!=', '<=', '>=', '&&', '||']);

// parser.js — loosest of all operators, || below &&:
const INFIX = {
  '||': [1, 2], '&&': [2, 3],
  '==': [3, 4], '!=': [3, 4],
  '<': [5, 6], '>': [5, 6], '<=': [5, 6], '>=': [5, 6],
  '+': [10, 11], '-': [10, 11],
  '*': [20, 21], '/': [20, 21],
};

// interpreter.js — top of applyOp:
    if (op === '&&' || op === '||') {
      requireType(l, 'boolean', node, `"${op}"`);
      requireType(r, 'boolean', node, `"${op}"`);
      return op === '&&' ? l && r : l || r;
    }
```

WHY: placing `[1,2]`/`[2,3]` *below* `==`'s `[3,4]` is the entire design decision — it makes `1 == 1 && 2 == 2` group as comparisons-first without touching any code, because in a Pratt parser precedence is data. The `requireType` calls extend Tiny's refusal to coerce. One honest limitation to notice: `applyOp` receives both sides already evaluated, so this `&&` does not short-circuit — real short-circuiting would need a special case in `evaluate` that checks `l` before evaluating `node.right`.

### 4. The untested corners

```js
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { run } from './refactored/interpreter.js';

test('string equality works; cross-type == is false, never coerced', () => {
  assert.deepEqual(run('print "a" == "a";'), ['true']);
  assert.deepEqual(run('print "1" == 1;'), ['false']);
});

test('ordering is numbers-only', () => {
  assert.throws(() => run('print "a" < "b";'), /"<" needs a number/);
});

test('assignment updates the NEAREST declaration, not the outermost', () => {
  assert.deepEqual(run(`
    let x = 1;
    if (true) {
      let x = 2;
      if (true) { x = 10; }
      print x;
    }
    print x;
  `), ['10', '1']);
});
```

WHY: (a) works because `valueEquals` compares types first, then values — so `"1" == 1` is `false` by design, not accident; (b) works because `<` sits in the numbers-only half of `applyOp`. The third test is the sharpest: `assign` walks the chain and stops at the *first* env that has the name, so the innermost `x` (value 2) gets the 10 while the outer `x` keeps its 1. That "stop at nearest" rule is exactly how JavaScript closures behave. (All verified with node.)

### 5. `break`

```js
// lexer.js:
const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'print', 'true', 'false', 'break']);

// parser.js — in parseStatement:
    if (at('break')) {
      next();
      expect(';');
      return { type: 'break', line: token.line };
    }

// interpreter.js:
class BreakSignal {} // a control-flow message, deliberately NOT an Error

// in exec's switch:
      case 'break': throw new BreakSignal();

// the while case wraps its body:
          if (!cond) return;
          try {
            exec(node.body, env);
          } catch (signal) {
            if (signal instanceof BreakSignal) return; // leave THIS loop only
            throw signal;
          }

// and run() converts strays into a real error:
  try {
    exec(program, new Environment());
  } catch (signal) {
    if (signal instanceof BreakSignal) throw new TinyError('"break" outside a loop', 0, 0);
    throw signal;
  }
```

WHY: `break` must jump from an arbitrary depth of nested blocks straight out of the loop — plain returns can't do that, but a throw unwinds every frame in between for free, exactly like backtracking used the call stack as an undo log. Catching *only* `BreakSignal` (and rethrowing the rest) keeps real `TinyError`s flowing; because each `while` catches its own body's signal, an inner `break` never touches the outer loop. Verified with node: `['0','1','2','done']`, nested loops produce `['0 0','0 1','1 0','1 1']`, and top-level `break;` throws the friendly error.

/**
 * Tiny's interpreter: walk the AST, carry an ENVIRONMENT.
 *
 * The environment chain IS the scoping model, in 20 lines:
 *   - each block gets a child environment
 *   - `let` declares in the CURRENT env (shadowing = a nearer link
 *     in the chain — nothing is overwritten)
 *   - assignment WALKS THE CHAIN to find where the variable lives
 *     (so inner blocks can update outer variables)
 *   - lookup walks the same chain; falling off the end is a
 *     positioned error, not `undefined`
 *
 * When the block ends, its environment is simply dropped — variable
 * lifetime for free. This chain-of-scopes is exactly how JS itself
 * works; closures are environments that outlive their block.
 */
import { parse } from './parser.js';
import { TinyError } from './lexer.js';

class Environment {
  constructor(parent = null) {
    this.vars = new Map();
    this.parent = parent;
  }

  declare(name, value, node) {
    if (this.vars.has(name)) {
      throw new TinyError(`"${name}" is already declared in this scope`, node.line ?? 0, 0);
    }
    this.vars.set(name, value);
  }

  assign(name, value, node) {
    for (let env = this; env; env = env.parent) {
      if (env.vars.has(name)) return env.vars.set(name, value);
    }
    throw new TinyError(`Cannot assign to undeclared variable "${name}" — did you mean "let"?`,
      node.line ?? 0, 0);
  }

  lookup(name, node) {
    for (let env = this; env; env = env.parent) {
      if (env.vars.has(name)) return env.vars.get(name);
    }
    throw new TinyError(`Unknown variable "${name}"`, node.line ?? 0, node.col ?? 0);
  }
}

const typeOf = (v) => (typeof v === 'boolean' ? 'boolean' : typeof v === 'string' ? 'string' : 'number');

/** run(source) -> array of printed lines. Output is DATA (returned),
 *  not a console side effect — which is what makes the tests clean. */
export function run(source, { maxSteps = 1_000_000 } = {}) {
  const program = parse(source);
  const output = [];
  let steps = 0;

  function exec(node, env) {
    if (steps++ > maxSteps) throw new TinyError('Program ran too long (infinite loop?)', 0, 0);

    switch (node.type) {
      case 'block': {
        const child = new Environment(env); // a fresh scope per block
        for (const statement of node.statements) exec(statement, child);
        return;
      }
      case 'let': return env.declare(node.name, evaluate(node.value, env), node);
      case 'assign': return env.assign(node.name, evaluate(node.value, env), node);
      case 'print': return void output.push(stringify(evaluate(node.value, env)));
      case 'if': {
        const cond = evaluate(node.condition, env);
        requireType(cond, 'boolean', node.condition, 'if condition');
        if (cond) exec(node.then, env);
        else if (node.otherwise) exec(node.otherwise, env);
        return;
      }
      case 'while': {
        while (true) {
          if (steps++ > maxSteps) throw new TinyError('Program ran too long (infinite loop?)', 0, 0);
          const cond = evaluate(node.condition, env);
          requireType(cond, 'boolean', node.condition, 'while condition');
          if (!cond) return;
          exec(node.body, env);
        }
      }
    }
  }

  function evaluate(node, env) {
    switch (node.type) {
      case 'number':
      case 'string':
      case 'boolean':
        return node.value;
      case 'var': return env.lookup(node.name, node);
      case 'neg': {
        const v = evaluate(node.operand, env);
        requireType(v, 'number', node, 'unary minus');
        return -v;
      }
      case 'not': {
        const v = evaluate(node.operand, env);
        requireType(v, 'boolean', node, '"!"');
        return !v;
      }
      case 'binop': {
        const l = evaluate(node.left, env);
        const r = evaluate(node.right, env);
        return applyOp(node, l, r);
      }
    }
  }

  function applyOp(node, l, r) {
    const { op } = node;
    if (op === '==') return valueEquals(l, r);
    if (op === '!=') return !valueEquals(l, r);
    if (op === '+') {
      // + is numbers OR strings — but never a silent mix (JS's
      // "1" + 2 === "12" is a bug factory Tiny declines to copy)
      if (typeOf(l) === 'number' && typeOf(r) === 'number') return l + r;
      if (typeOf(l) === 'string' && typeOf(r) === 'string') return l + r;
      throw new TinyError(`Cannot add ${typeOf(l)} and ${typeOf(r)}`, node.line ?? 0, node.col ?? 0);
    }
    // everything else is numbers-only
    requireType(l, 'number', node, `"${op}"`);
    requireType(r, 'number', node, `"${op}"`);
    switch (op) {
      case '-': return l - r;
      case '*': return l * r;
      case '/':
        if (r === 0) throw new TinyError('Division by zero', node.line ?? 0, node.col ?? 0);
        return l / r;
      case '<': return l < r;
      case '>': return l > r;
      case '<=': return l <= r;
      case '>=': return l >= r;
    }
  }

  function requireType(value, type, node, where) {
    if (typeOf(value) !== type) {
      throw new TinyError(`${where} needs a ${type}, got ${typeOf(value)} (${stringify(value)})`,
        node.line ?? 0, node.col ?? 0);
    }
  }

  const valueEquals = (l, r) => typeOf(l) === typeOf(r) && l === r;
  const stringify = (v) => String(v);

  exec(program, new Environment());
  return output;
}

/**
 * Tiny's lexer: source -> tokens, each carrying line/column.
 * (Project 69's tokenizer, grown keywords, strings, two-char
 * operators, and comments.)
 */

export class TinyError extends Error {
  constructor(message, line, col) {
    super(`${message} (line ${line}, col ${col})`);
    this.name = 'TinyError';
    this.line = line;
    this.col = col;
  }
}

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'print', 'true', 'false']);
const TWO_CHAR = new Set(['==', '!=', '<=', '>=']);
const ONE_CHAR = new Set(['+', '-', '*', '/', '(', ')', '{', '}', ';', '=', '<', '>', '!']);

export function lex(source) {
  const tokens = [];
  let i = 0, line = 1, col = 1;

  const push = (type, value, len) => {
    tokens.push({ type, value, line, col });
    i += len;
    col += len;
  };

  while (i < source.length) {
    const ch = source[i];

    if (ch === '\n') { i++; line++; col = 1; continue; }
    if (ch === ' ' || ch === '\t' || ch === '\r') { i++; col++; continue; }
    if (ch === '#') { while (i < source.length && source[i] !== '\n') i++; continue; } // comments

    if (TWO_CHAR.has(source.slice(i, i + 2))) { push('op', source.slice(i, i + 2), 2); continue; }
    if (ONE_CHAR.has(ch)) { push('op', ch, 1); continue; }

    if (ch >= '0' && ch <= '9') {
      const m = /^\d+(\.\d+)?/.exec(source.slice(i));
      push('number', Number(m[0]), m[0].length);
      continue;
    }

    if (ch === '"') {
      const end = source.indexOf('"', i + 1);
      if (end === -1) throw new TinyError('Unterminated string', line, col);
      const raw = source.slice(i + 1, end);
      if (raw.includes('\n')) throw new TinyError('Strings cannot span lines', line, col);
      push('string', raw, raw.length + 2);
      continue;
    }

    if (/[a-zA-Z_]/.test(ch)) {
      const m = /^[a-zA-Z_]\w*/.exec(source.slice(i));
      push(KEYWORDS.has(m[0]) ? m[0] : 'name', m[0], m[0].length);
      continue;
    }

    throw new TinyError(`Unexpected character "${ch}"`, line, col);
  }

  tokens.push({ type: 'eof', line, col });
  return tokens;
}

/**
 * Tiny's parser: tokens -> an AST. Two layers, two techniques:
 *
 *   STATEMENTS by recursive descent (one function per statement
 *   kind — project 69's shape), because statement syntax is keyword-
 *   led and has no precedence.
 *
 *   EXPRESSIONS by Pratt (project 70's table + loop), because
 *   operators are all about precedence and associativity.
 *
 * The grammar:
 *   program   := statement*
 *   statement := "let" name "=" expr ";"
 *              | name "=" expr ";"
 *              | "print" expr ";"
 *              | "if" "(" expr ")" block ("else" block)?
 *              | "while" "(" expr ")" block
 *   block     := "{" statement* "}"
 */
import { lex, TinyError } from './lexer.js';

const INFIX = {
  '==': [3, 4], '!=': [3, 4],
  '<': [5, 6], '>': [5, 6], '<=': [5, 6], '>=': [5, 6],
  '+': [10, 11], '-': [10, 11],
  '*': [20, 21], '/': [20, 21],
};
const UNARY_BP = 30;

export function parse(source) {
  const tokens = lex(source);
  let current = 0;

  const peek = () => tokens[current];
  const next = () => tokens[current++];
  const at = (typeOrValue) =>
    peek().type === typeOrValue || (peek().type === 'op' && peek().value === typeOrValue);

  function expect(typeOrValue, what = `"${typeOrValue}"`) {
    if (!at(typeOrValue)) {
      const t = peek();
      throw new TinyError(`Expected ${what} but found "${t.value ?? t.type}"`, t.line, t.col);
    }
    return next();
  }

  // ---- statements ----------------------------------------------------

  function parseProgram(endsAt = 'eof') {
    const statements = [];
    while (!at(endsAt)) statements.push(parseStatement());
    return { type: 'block', statements };
  }

  function parseBlock() {
    expect('{');
    const block = parseProgram('}');
    expect('}');
    return block;
  }

  function parseStatement() {
    const token = peek();

    if (at('let')) {
      next();
      const name = expect('name', 'a variable name').value;
      expect('=');
      const value = parseExpression(0);
      expect(';');
      return { type: 'let', name, value, line: token.line };
    }
    if (at('print')) {
      next();
      const value = parseExpression(0);
      expect(';');
      return { type: 'print', value };
    }
    if (at('if')) {
      next();
      expect('(');
      const condition = parseExpression(0);
      expect(')');
      const then = parseBlock();
      let otherwise = null;
      if (at('else')) { next(); otherwise = at('if') ? parseStatement() : parseBlock(); } // else-if chains
      return { type: 'if', condition, then, otherwise };
    }
    if (at('while')) {
      next();
      expect('(');
      const condition = parseExpression(0);
      expect(')');
      return { type: 'while', condition, body: parseBlock() };
    }
    if (at('name') && tokens[current + 1]?.value === '=') {
      const name = next().value;
      next(); // =
      const value = parseExpression(0);
      expect(';');
      return { type: 'assign', name, value, line: token.line };
    }

    throw new TinyError(`Expected a statement but found "${token.value ?? token.type}"`,
      token.line, token.col);
  }

  // ---- expressions (Pratt, project 70) ---------------------------------

  function parsePrefix() {
    const token = next();
    if (token.type === 'number') return { type: 'number', value: token.value };
    if (token.type === 'string') return { type: 'string', value: token.value };
    if (token.type === 'true') return { type: 'boolean', value: true };
    if (token.type === 'false') return { type: 'boolean', value: false };
    if (token.type === 'name') return { type: 'var', name: token.value, line: token.line, col: token.col };
    if (token.value === '(') {
      const inner = parseExpression(0);
      expect(')');
      return inner;
    }
    if (token.value === '-') return { type: 'neg', operand: parseExpression(UNARY_BP) };
    if (token.value === '!') return { type: 'not', operand: parseExpression(UNARY_BP) };
    throw new TinyError(`Expected an expression but found "${token.value ?? token.type}"`,
      token.line, token.col);
  }

  function parseExpression(minBP) {
    let left = parsePrefix();
    while (peek().type === 'op' && INFIX[peek().value] && INFIX[peek().value][0] >= minBP) {
      const opToken = next();
      left = {
        type: 'binop', op: opToken.value, left,
        right: parseExpression(INFIX[opToken.value][1]),
        line: opToken.line, col: opToken.col,
      };
    }
    return left;
  }

  return parseProgram();
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { run } from './interpreter.js';
import { TinyError } from './lexer.js';

test('the program the original could not represent: blocks, else, nesting', () => {
  const out = run(`
    let x = 3;
    if (x > 2) {
      print "big";
      print x * 10;
    } else {
      print "small";
    }
  `);
  assert.deepEqual(out, ['big', '30']);
});

test('fibonacci — a real loop with a multi-statement body', () => {
  const out = run(`
    let a = 0;
    let b = 1;
    let n = 0;
    while (n < 8) {
      print a;
      let next = a + b;
      a = b;
      b = next;
      n = n + 1;
    }
  `);
  assert.deepEqual(out, ['0', '1', '1', '2', '3', '5', '8', '13']);
});

test('SCOPING: a block-local let is dropped when the block ends', () => {
